	}

pub(crate) fn begin_native_snapshot_before(
    &mut self,
    mut request: ServiceRequest<'_>,
    deadline: Instant,
) -> NativeSnapshotAdmission {
    let _scope = crate::request_deadline::RequestDeadlineScope::enter(deadline);
    if crate::request_deadline::current().is_none_or(|limit| Instant::now() >= limit) {
        erase_json(&mut request.body);
        return NativeSnapshotAdmission::Execute(RequestExecution::Complete(Response::error(
            503,
            "snapshot admission deadline exceeded",
        )));
    }
    let accepted = matches!(
        request.path,
        "sys/storage/raft/snapshot" | "sys/storage/raft/snapshot-force" | NATIVE_HA_REPAIR_PATH
    );
    #[cfg(feature = "native-v6-storage")]
    let accepted = accepted
        || (request.path == crate::engines::kv2_lossless_export::PATH
            && matches!(request.method, "GET" | "HEAD"));
    if !accepted {
        erase_json(&mut request.body);
        return NativeSnapshotAdmission::Execute(RequestExecution::Complete(Response::error(
            400,
            "invalid native snapshot route",
        )));
    }
    // This is before authentication/finite-use persistence, staging and
    // JSON HA forwarding. The receiving leader independently authorizes
    // the original request; observing a leader never grants authority.
    match self.configured_standby_destination() {
        Ok(Some(origin)) => {
            let now = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap_or(Duration::ZERO)
                .as_secs();
            let fingerprint = self.request_fingerprint(
                request.method,
                request.path,
                request.namespace,
                request.token,
            );
            erase_json(&mut request.body);
            if self
                .audit_event("request", &fingerprint, now, None)
                .is_err()
            {
                return NativeSnapshotAdmission::Execute(RequestExecution::Complete(
                    Response::error(503, "snapshot redirect audit unavailable"),
                ));
            }
            if self
                .audit_event("response", &fingerprint, now, Some(307))
                .is_err()
            {
                crate::service::openbao_wrapper::fence(&self.openbao_wrapper_owner);
                self.recovery_required = true;
                self.ha_activation = None;
                return NativeSnapshotAdmission::Execute(RequestExecution::Complete(
                    Response::error(503, "snapshot redirect response audit unavailable"),
                ));
            }
            return NativeSnapshotAdmission::Redirect(origin);
        }
        Err(response) => {
            erase_json(&mut request.body);
            return NativeSnapshotAdmission::Execute(RequestExecution::Complete(response));
        }
        Ok(None) => {}
    }
    // Pair wall time and the monotonic anchor before reconciliation, audit,
    // authentication and finite-use persistence can spend admission time.
    let started = Instant::now();
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or(Duration::ZERO);
    let previous_clock = self.native_snapshot_clock.replace((started, now));
    let previous = self.native_snapshot_transport;
    self.native_snapshot_transport = true;
    let result = self.begin_request_before(request, deadline, false);
    self.native_snapshot_transport = previous;
    self.native_snapshot_clock = previous_clock;
    NativeSnapshotAdmission::Execute(result)
}

pub(super) fn configured_standby_destination(
    &self,
) -> Result<Option<TrustedSnapshotOrigin>, Response> {
    let Some(process) = self.ha.as_ref() else {
        return Ok(None);
    };
    if self.state.is_none() {
        return Err(Response::error(503, "server is sealed"));
    }
    let process = process
        .lock_for_request()
        .map_err(|_| Response::error(503, "HA process lock is unavailable"))?;
    let observation = process
        .leader_status()
        .map_err(|_| Response::error(503, "HA leader state is unavailable"))?;
    let leader = observation
        .leader
        .ok_or_else(|| Response::error(503, "HA cluster has no elected leader"))?;
    if leader == observation.local_id {
        return Ok(None);
    }
    process
        .api_address(leader)
        .map(|origin| Some(TrustedSnapshotOrigin(origin.to_owned())))
        .ok_or_else(|| Response::error(503, "HA leader API address is unavailable"))
}

Self::Redirect {
    origin,
    target,
    headers,
} => {
    // An unread upload can still be in another TLS record. Build
    // the complete head before the first transport write, instead
    // of emitting the status/Location prefix as its own record.
    // The fixed allowance covers the standard/date/timing headers;
    // existing variable fields keep their original input bounds.
    let capacity = origin
        .as_str()
        .len()
        .checked_add(target.as_str().len())
        .and_then(|size| size.checked_add(namespace.len()))
        .and_then(|size| size.checked_add(512))
        // Local routing may retain at most four original numeric
        // quota fields, each with a value of at most twenty digits.
        .and_then(|size| size.checked_add(if headers.is_empty() { 0 } else { 512 }))
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "redirect header length overflow",
            )
        })?;
    let mut buffer = Zeroizing::new(vec![0; capacity]);
    let used = {
        // Cursor over a fixed slice cannot grow the allocation.
        let mut header = io::Cursor::new(buffer.as_mut_slice());
        write!(
            header,
            "HTTP/1.1 307 Temporary Redirect\r\nLocation: {}{}\r\nContent-Length: 0\r\n",
            origin.as_str(),
            target.as_str(),
        )?;
        headers.write(&mut header)?;
        write_standard_headers(&mut header, namespace)?;
        header.write_all(b"\r\n")?;
        header.position() as usize
    };
    writer.write_all(&buffer[..used])?;
    writer.flush()

pub(super) fn execute(
    service: &Arc<Mutex<Service>>,
    request: ServiceRequest<'_>,
    native: NativeRequest,
    reader: &mut impl Read,
    deadline: Instant,
) -> NativeReply {
    let _scope = crate::request_deadline::RequestDeadlineScope::enter(deadline);
    let execution = match lock_until(service, deadline) {
        Ok(mut writer) => writer.begin_native_snapshot_before(request, deadline),
        Err(_) => return NativeReply::Json(Response::error(503, "snapshot admission unavailable")),
    };
    let execution = match execution {
        NativeSnapshotAdmission::Execute(execution) => execution,
        NativeSnapshotAdmission::Redirect(origin) => {
            // Do not read/replay the upload, allocate a spool or transport any
            // archive in the ordinary bounded HA forwarding frame.
            return NativeReply::Redirect {
                origin,
                target: RedirectTarget::Native(native.target),
                headers: Default::default(),
            };
        }
    };
    let mut pending = match execution {
        RequestExecution::Complete(response) => {
            return rejected_upload_response(reader, native.body, deadline, response);
        }
        RequestExecution::External(pending) => pending,
    };
    #[cfg(feature = "native-v6-storage")]
    let lossless_download = pending.has_lossless_download();
    let (observation, file) = match BodyReader::new(reader, native.body, deadline) {
        Ok(mut reader) => pending.execute_snapshot_transfer(&mut reader),
        Err(_) => (
            crate::service::ExternalEffectResult::SnapshotTransfer(Err(Response::error(
                400,
                "invalid snapshot body framing",
            ))),
            None,
        ),
    };

let maximum = if matches!(
